const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey(new Date()), parseDate=s=>new Date(s+'T00:00:00'), addDays=(s,n)=>{let d=parseDate(s);d.setDate(d.getDate()+n);return dateKey(d)}, minutes=s=>Number(s.split(':')[0])*60+Number(s.split(':')[1]);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats={Work:['⌘','#e8edde','#7b8f62'],Study:['▤','#ede9df','#a08d66'],Wellness:['♧','#e7eddf','#82946b'],Meeting:['▧','#e8e8f0','#8d89a4'],Personal:['☕','#f1e8de','#b49a7c'],Sleep:['☾','#e5eaf0','#8a9bae'],Office:['▣','#e7eae5','#7e9078'],Custom:['✳','#eee6ea','#a58896']};
let state=window.dayformInitial;let storageFailed=false;
if(!state){state={activities:[],done:{},logs:[],reminders:false,seed:true};const seeds=[['A slow start & morning stretch','Wellness','07:00','07:30'],['Deep work · make something good','Work','09:00','11:00'],['Product team catch-up','Meeting','11:30','12:00'],['Lunch & a little reset','Personal','12:30','13:30'],['Learn something new','Study','14:00','15:30'],['Move your body','Wellness','17:30','18:30'],['Wind down & recharge','Sleep','22:00','07:00']];seeds.forEach((a,i)=>state.activities.push({id:crypto.randomUUID(),title:a[0],category:a[1],date:today(),start:a[2],end:a[3],repeat:'none',link:'',notes:'Sample activity — make this day your own.'}));}
state.done ||= {}; state.logs ||= []; state.completionMeta ||= {}; state.emailReminders ??= true;
const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;const zoneChanged=state.timezone!==zone;state.timezone=zone;
const VIEWS=['dashboard','calendar','timetable','activities','analytics','notifications','settings','help','admin'];
let activityQuery='',activityCat='all';
const NOTIFY_LEAD=10*60000;let startTimer=null,emailEntries=null;
const ticketLabel={open:'Open',in_progress:'In progress',resolved:'Resolved',closed:'Closed'},ticketCats={help:'Help',bug:'Something’s broken',account:'My account',feedback:'Feedback',access:'Access request'};
let myTicketList=null,inboxList=null,openTicketId=null;
const cloud=()=>window.dayformCloud;
const dayIso=d=>dateKey(d),daysAgo=n=>addDays(today(),-n);
let adminTab='overview',adminData=null,adminLoading=false,adminUserQuery='',adminUserStatus='all',adminTicketStatus='open',adminTicketId=null;
let view=VIEWS.includes(location.pathname.slice(1))?location.pathname.slice(1):'dashboard',selected=today(),filter='all',charts=[],calendarMonth=parseDate(today());
function save(){window.dayformSave(state)}
function go(v){if(!VIEWS.includes(v)||(v==='admin'&&!window.dayformIsAdmin))v='dashboard';if(location.pathname!=='/'+v)history.pushState(null,'','/'+v);view=v;render();window.scrollTo(0,0)}
function completionRate(d){const ev=events(d);return ev.length?ev.filter(a=>state.done[a.key]).length/ev.length:0}
function log(type,message){state.logs.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),type,message});state.logs=state.logs.slice(0,300);save();const audit=document.querySelector('#audit-log');if(audit?.isConnected)audit.innerHTML=auditRows();const count=document.querySelector('#log-count');if(count)count.textContent=state.logs.length+(emailEntries?.length||0)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function duration(a){let n=minutes(a.end)-minutes(a.start);return n<=0?n+1440:n}
function occurs(a,date){if(date<a.date)return false;let s=parseDate(a.date),d=parseDate(date);if(a.repeat==='none')return date===a.date;if(a.repeat==='daily')return true;if(a.repeat==='weekly')return s.getDay()===d.getDay();const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();if(a.repeat==='monthly')return d.getDate()===Math.min(s.getDate(),last);return d.getMonth()===s.getMonth()&&d.getDate()===Math.min(s.getDate(),last)}
function events(date){return state.activities.filter(a=>occurs(a,date)).map(a=>({...a,key:a.id+'@'+date,day:date,begin:new Date(date+'T'+a.start),finish:new Date(new Date(date+'T'+a.start).getTime()+duration(a)*60000)})).sort((a,b)=>a.start.localeCompare(b.start))}
function visibleEvents(date){return [...events(addDays(date,-1)).filter(a=>a.finish>parseDate(date)),...events(date)]}
function occurrence(key){const day=key.slice(key.lastIndexOf('@')+1);return events(day).find(a=>a.key===key)}
// A day locks at local midnight: occurrences that finished before today began can no longer be checked in or undone.
function dayLocked(a,now=Date.now()){return a.finish.getTime()<=parseDate(dateKey(new Date(now))).getTime()}
function completionError(a,time,now=Date.now()){const value=new Date(time).getTime();return !a?'Activity no longer exists.':now<a.begin.getTime()?'Completion unlocks at the scheduled start.':dayLocked(a,now)?'This day has ended and is locked. Past days can’t be edited.':!Number.isFinite(value)?'Choose a valid completion time.':value<a.begin.getTime()?'Completion cannot be before the activity starts.':value>now?'Completion cannot be in the future. Choose the actual time you finished.':''}
function dayAllocation(date){let slots=Array(1440).fill('Unplanned');for(const d of [addDays(date,-1),date])for(const a of events(d)){let base=d===date?0:-1440;let start=base+minutes(a.start);for(let i=Math.max(0,start);i<Math.min(1440,start+duration(a));i++)slots[i]=a.category}let totals={};slots.forEach(c=>totals[c]=(totals[c]||0)+1);return totals}
function hours(n){return Number((n/60).toFixed(1))+'h'}
function fmtTime(t){const [h,m]=t.split(':');return `${Number(h)%12||12}:${m} ${Number(h)<12?'AM':'PM'}`}
function catStyle(c){return `--cat-bg:${cats[c][1]};--cat-color:${cats[c][2]}`}
function activityRow(a){let done=state.done[a.key],locked=Date.now()<a.begin.getTime(),closed=dayLocked(a),late=!done&&!closed&&Date.now()>a.finish.getTime(),pastOnce=a.repeat==='none'&&closed;return `<div class="activity-row"><div class="time-label">${fmtTime(a.start).replace(' ','<br>')}</div><article class="activity ${done?'done':locked?'':'next'}" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div class="activity-info"><button class="activity-title activity-title-button" data-details="${a.key}">${esc(a.title)}</button><div class="activity-meta"><span>${fmtTime(a.start)} – ${fmtTime(a.end)}</span><span>· ${hours(duration(a))}</span><span class="tag">${a.category}</span>${a.repeat!=='none'?'<span title="Repeating activity">↻</span>':''}${late?'<span>Overdue · check in before midnight</span>':''}${closed?`<span class="locked-tag">🔒 ${done?'Locked':'Missed · locked'}</span>`:''}${locked?'<span>⌑ Scheduled</span>':''}${a.link?`<a target="_blank" rel="noopener" href="${esc(a.link)}">Join ↗</a>`:''}</div></div><div class="activity-actions"><input type="checkbox" aria-label="Complete ${esc(a.title)}" data-complete="${a.key}" ${done?'checked':''} ${locked?'disabled title="Completion unlocks at the scheduled start"':closed?'disabled title="This day has ended and is locked"':''}><button class="mini-btn" data-edit="${a.id}" ${pastOnce?'disabled ':''}title="${pastOnce?'Past activities are locked':'Edit or reschedule'}" aria-label="Reschedule ${esc(a.title)}">↗</button><button class="mini-btn" data-delete="${a.id}" title="Delete activity" aria-label="Delete ${esc(a.title)}">×</button></div></article></div>`}
function header(title,sub,tag='YOUR EVERYDAY, REIMAGINED'){return `<div class="page-heading"><div><span class="heading-tag">${tag}</span><h1>${title}</h1><p>${sub}</p></div><button class="primary" data-add>＋ <span>Add activity</span></button></div>`}
function toolbar(){return `<div class="toolbar"><button class="soft-button" data-shift="-1" aria-label="Previous day">‹</button><input class="date-picker" type="date" id="selected-date" aria-label="Selected date" value="${selected}"><button class="soft-button" data-shift="1" aria-label="Next day">›</button><button class="soft-button" id="today">Today</button><div class="right"><span class="week-pill">${[['dashboard','Day'],['timetable','24 hours'],['calendar','Month']].map(([v,t])=>`<button class="${view===v?'active':''}" data-view="${v}">${t}</button>`).join('')}</span></div></div>`}
function stats(){let ev=visibleEvents(selected),done=ev.filter(a=>state.done[a.key]).length,allocation=dayAllocation(selected),planned=1440-(allocation.Unplanned||0),late=ev.filter(a=>!state.done[a.key]&&Date.now()>a.finish&&!dayLocked(a)).length;return `<div class="stats">${[['Daily progress','◉',ev.length?Math.round(done/ev.length*100)+'%':'0%',`${done} of ${ev.length} activities complete`],['Planned time','◷',hours(planned)+' <em>/ 24h</em>',`${hours(1440-planned)} of breathing room`],['Activities today','▦',String(ev.length).padStart(2,'0'),'A little structure, a lot of possibility'],['Needs attention','↗',String(late).padStart(2,'0'),late?'Overdue activities to revisit':'You’re right where you need to be']].map((s,i)=>`<div class="stat"><div class="stat-label">${s[0]}<span>${s[1]}</span></div><div class="stat-value">${s[2]}</div><div class="stat-note">${s[3]}</div>${i===0?'<div class="tiny-bars" aria-hidden="true">'+lastDays(7).map(d=>`<i title="${d}: ${Math.round(completionRate(d)*100)}% complete" style="height:${4+Math.round(completionRate(d)*28)}px"></i>`).join('')+'</div>':''}</div>`).join('')}</div>`}
function allocationCard(){let al=dayAllocation(selected);return `<section class="card"><div class="card-head"><div><h2>A little of everything</h2><p>Your 24 hours, in perspective</p></div><span class="muted">◴</span></div><div class="chart-wrap"><canvas id="allocation" aria-label="24-hour time allocation chart" role="img"></canvas><div class="chart-center"><strong>24<span style="font-size:13px">h</span></strong><small>YOUR WHOLE DAY</small></div></div><div class="legend">${Object.entries(al).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<div class="legend-item"><i style="background:${cats[c]?.[2]||'#e7ebdf'}"></i>${c}<b>${hours(n)}</b></div>`).join('')}</div></section>`}
function upcoming(){let next=[];for(let i=0;i<8;i++)next.push(...events(addDays(today(),i)).filter(a=>a.begin>Date.now()&&!state.done[a.key]));next=next.slice(0,3);return `<section class="card"><div class="card-head"><div><h2>On the horizon <span class="count-badge">UP NEXT</span></h2><p>A gentle heads-up for what’s ahead</p></div></div><div class="upcoming">${next.map(a=>`<div class="upcoming-row" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div><h3>${esc(a.title)}</h3><small>${a.day===today()?'Today':parseDate(a.day).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${fmtTime(a.start)}</small></div><button class="when" data-details="${a.key}">↗</button></div>`).join('')||'<div class="empty">A clear horizon. Make space for something good.</div>'}</div></section>`}
function dashboard(){let ev=visibleEvents(selected),filtered=ev.filter(a=>filter==='all'||(filter==='done'?state.done[a.key]:!state.done[a.key]));return header(selected===today()?'A little intention. A better day.':'Make room for your day.','Your plans, your pace. Let’s make today feel good.')+toolbar()+stats()+nowCard()+completionNudge()+`<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Your daily flow <span class="count-badge">${ev.length} activities</span></h2><p>${parseDate(selected).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} · One thing at a time</p></div><button class="text-button" data-view="timetable">Full timetable ↗</button></div><div class="schedule-tabs">${[['all','All activities'],['pending','To do'],['done','Completed']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><div class="timeline">${filtered.map(activityRow).join('')||'<div class="empty">Nothing here yet.<br>Add an activity to give your day a little direction.</div>'}</div><div style="padding:0 22px 20px"><button class="text-button" data-add>＋ Make room for something else</button></div></section><div class="right-stack">${allocationCard()}${upcoming()}<div class="balance-banner"><span>✳</span><div><h3>Rest is part of the plan.</h3><p>A little breathing room goes a long way.<br>You don’t have to fill every hour.</p></div></div></div></div><div class="lower-grid"><section class="card"><div class="card-head"><div><h2>Finding your rhythm</h2><p>Completed activities over the last 7 days</p></div><button class="text-button" data-view="analytics">Explore insights ↗</button></div><div class="bar-chart"><canvas id="week-chart" role="img" aria-label="Completed activities over seven days"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Small steps. Real progress.</h2><p>Your activity check-in, one day at a time</p></div><span>✧</span></div><div class="rhythm">${Array.from({length:14},(_,i)=>{let d=addDays(selected,i-13);return `<i title="${d}" class="${events(d).some(a=>state.done[a.key])?'filled':''}"></i>`}).join('')}</div><p class="insight-text">${state.seed?'Start with a sample day, then make it yours. Edit or remove any activity to build a routine that fits.':'Consistency grows one check-in at a time. Your progress appears here as you complete activities.'}</p></section></div>`}
function calendar(){let start=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),first=new Date(start);first.setDate(1-((start.getDay()+6)%7));return header('A wider view of your days.','Room for your routines, and the things you look forward to.','THE BIGGER PICTURE')+`<div class="toolbar"><button class="soft-button" id="prev-month">‹</button><h2>${start.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><button class="soft-button" id="next-month">›</button><button class="soft-button" id="month-today">This month</button></div><div class="card calendar-card"><div class="calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="day-heading">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{let d=new Date(first);d.setDate(first.getDate()+i);let key=dateKey(d),ev=events(key);return `<div class="calendar-day ${key===today()?'today':''} ${d.getMonth()!==start.getMonth()?'outside':''}"><button data-day="${key}">${d.getDate()}</button>${ev.slice(0,3).map(a=>`<button class="calendar-event" style="${catStyle(a.category)}" data-details="${a.key}" aria-label="${esc(a.title)} at ${fmtTime(a.start)}">${a.start} ${esc(a.title)}</button>`).join('')}${ev.length>3?`<button class="text-button" data-day="${key}">+ ${ev.length-3} more</button>`:''}</div>`}).join('')}</div></div>`}
function timetable(){const offset=(parseDate(selected).getDay()+6)%7,days=Array.from({length:7},(_,i)=>addDays(selected,i-offset));return header('Your week, beautifully in view.','Hover or focus to preview. Click an activity for details, or an empty cell to plan that hour.','YOUR WEEKLY TIMETABLE')+toolbar()+`<section class="card timetable-card"><div class="card-head"><div><h2>24 hours · 7 days</h2><p>All times local · Overnight sleep carries into the next morning</p></div><button class="soft-button" id="current-hour">Jump to this hour ↓</button></div><div class="week-scroll"><table class="week-table"><caption class="sr-only">Weekly activities by hour and day</caption><thead><tr><th scope="col">TIME</th>${days.map(d=>`<th scope="col" class="${d===selected?'selected-day':''}"><button data-week-day="${d}">${parseDate(d).toLocaleDateString(undefined,{weekday:'short'})}<strong>${parseDate(d).getDate()}</strong></button></th>`).join('')}</tr></thead><tbody>${Array.from({length:24},(_,h)=>`<tr id="hour-${h}"><th scope="row">${String(h).padStart(2,'0')}:00</th>${days.map(d=>{const from=new Date(d+'T'+String(h).padStart(2,'0')+':00'),to=new Date(from.getTime()+3600000),list=visibleEvents(d).filter(a=>a.begin<to&&a.finish>from);return `<td class="${d===today()&&h===new Date().getHours()?'current-slot':''}">${list.map(a=>`<button class="slot-activity ${state.done[a.key]?'slot-done':''}" style="${catStyle(a.category)}" data-details="${a.key}" title="${esc(a.title)} · ${a.day} ${a.start}–${a.end} · ${state.done[a.key]?'Completed':Date.now()<a.begin?'Scheduled':Date.now()>a.finish?'Overdue':'In progress'}"><span>${cats[a.category][0]} ${esc(a.title)}</span><small>${a.start}–${a.end} ${state.done[a.key]?'✓':''}</small><span class="slot-preview">${a.category} · ${hours(duration(a))}<br>${a.day!==d?'Continues from yesterday · ':''}${a.repeat==='none'?'One-time':a.repeat+' repeat'}<br>Open details ↗</span></button>`).join('')||`<button class="empty-slot" data-slot-day="${d}" data-slot-hour="${h}" aria-label="Add activity on ${d} at ${h}:00">＋<span>Plan ${String(h).padStart(2,'0')}:00</span></button>`}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function lastDays(n){return Array.from({length:n},(_,i)=>addDays(selected,i-n+1))}
function analytics(){let days=lastDays(30),ev=days.flatMap(events).filter(a=>a.begin<=Date.now()),missed=days.filter(d=>d<today()&&events(d).length&&!events(d).some(a=>state.done[a.key])).length;let groups=Object.keys(cats).map(c=>{let list=ev.filter(a=>a.category===c),done=list.filter(a=>state.done[a.key]),delays=done.map(a=>Math.max(0,(new Date(state.done[a.key])-a.finish)/60000));return {c,total:list.length,done:done.length,overdue:list.filter(a=>!state.done[a.key]&&a.finish<Date.now()).length,delay:delays.length?Math.round(delays.reduce((a,b)=>a+b,0)/delays.length):0}}).filter(g=>g.total);return header('Understand your everyday.','Real patterns from your activity history. A little awareness goes a long way.','INSIGHTS & ANALYTICS')+toolbar()+insightStats()+`<div class="analytics-grid"><section class="card"><div class="card-head"><div><h2>Completion trend</h2><p>Daily completion rate · 30 days ending ${parseDate(selected).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</p></div></div><div class="bar-chart"><canvas id="trend-chart" role="img" aria-label="Daily completion rate over 30 days"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Where the week goes</h2><p>Planned hours by category · Last 7 days</p></div></div><div class="bar-chart"><canvas id="category-chart" role="img" aria-label="Planned hours by category over seven days"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Your weekly momentum</h2><p>Completed and scheduled activities · Last 7 days</p></div></div><div class="bar-chart"><canvas id="week-chart"></canvas></div></section>${allocationCard()}<section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Where your time finds its rhythm</h2><p>Last 30 days · ${missed} past scheduled days without a completion check-in</p></div></div><div class="table-wrap"><table><thead><tr><th>ACTIVITY CATEGORY</th><th>COMPLETION</th><th>OVERDUE</th><th>AVG. COMPLETION DELAY</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${cats[g.c][0]} &nbsp; ${g.c}</td><td>${g.done}/${g.total} <small>${Math.round(g.done/g.total*100)}% complete</small></td><td>${g.overdue}</td><td>${g.delay} min <small>After scheduled end</small></td></tr>`).join('')||'<tr><td colspan="4">No activity history for this period yet.</td></tr>'}</tbody></table></div></section><section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Activities that need a little care</h2><p>Overdue occurrences · Most delayed first</p></div></div><div class="timeline">${ev.filter(a=>!state.done[a.key]&&a.finish<Date.now()).sort((a,b)=>a.finish-b.finish).slice(0,10).map(a=>`<div style="margin-bottom:8px"><small>${a.day} · ${Math.floor((Date.now()-a.finish)/3600000)} hours overdue</small>${activityRow(a)}</div>`).join('')||'<div class="empty">No overdue activities. A little peace of mind.</div>'}</div></section></div>`}
function notifications(){return header('A gentle nudge, thoughtfully kept.','Browser notifications 10 minutes before each activity, and an email at 8 PM. Every change and send is recorded below.','NOTIFICATIONS & EMAIL')+notificationControls()+inboxCard()+`<section class="card"><div class="card-head"><div><h2>Notification & activity audit</h2><p>Permissions, on/off changes, notifications and emails sent</p></div><button class="text-button" id="export-log">Export log ↓</button></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>EVENT</th><th>DETAILS</th></tr></thead><tbody id="audit-log">${auditRows()}</tbody></table></div></section>`}
function settings(){return profileSection()+header('Make this space your own.','Simple preferences for an intentional everyday.','PREFERENCES')+`<section class="card settings-card"><h2>Your personal space</h2><div class="setting-row"><div><h3>Notifications & email</h3><p>Browser notifications 10 minutes before each activity: <b>${notificationsOn()?'on':'off'}</b>. 8 PM email: <b>${state.emailReminders?'on':'off'}</b>.</p></div><button class="soft-button" data-view="notifications">Manage ↗</button></div><div class="setting-row"><div><h3>Help & support</h3><p>Raise a ticket and follow replies from the Dayform team.</p></div><button class="soft-button" data-view="help">Open ↗</button></div>${window.dayformIsAdmin?'<div class="setting-row"><div><h3>Admin console</h3><p>Users, tickets, email activity and insights.</p></div><button class="soft-button" data-view="admin">Open ↗</button></div>':''}<div class="setting-row"><div><h3>Keep a copy of your plans</h3><p>Export activities, completion history, and audit events as JSON.<br>Your data is saved privately in Cloud Firestore. Reload another device to fetch the latest saved version.</p></div><button class="soft-button" id="export-data">Export backup ↓</button></div><div class="setting-row"><div><h3>Restore from backup</h3><p>Import a Dayform JSON backup. It replaces the planner saved in your account.</p></div><button class="soft-button" id="import-data">Import backup ↑</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="setting-row"><div><h3>Sample activities</h3><p>Remove the starter activities when you’re ready to begin.</p></div><button class="soft-button" id="clear-samples">Remove samples</button></div><div class="setting-row"><div><h3>Calendar export</h3><p>Download your schedule as an .ics calendar with repeat rules.</p></div><button class="soft-button" id="export-calendar">Export calendar ↓</button></div><div class="setting-row shortcuts-row"><div><h3>Keyboard shortcuts</h3><p class="shortcut-list"><span><kbd>N</kbd> New activity</span><span><kbd>/</kbd> Search activities</span><span><kbd>T</kbd> Jump to today</span><span><kbd>←</kbd><kbd>→</kbd> Previous / next day</span><span><kbd>1</kbd>–<kbd>7</kbd> Switch pages</span></p></div></div><p class="form-hint" style="margin-top:22px">Monthly and yearly repeats use the last day of shorter months. Overlapping activities share the 24-hour budget: later-starting activities take precedence.</p></section>`}
function drawCharts(){if(typeof Chart==='undefined')return;Chart.defaults.font.family="'DM Sans', sans-serif";Chart.defaults.color='#98a18d';if($('#allocation')){let al=dayAllocation(selected);charts.push(new Chart($('#allocation'),{type:'doughnut',data:{labels:Object.keys(al),datasets:[{data:Object.values(al),backgroundColor:Object.keys(al).map(c=>cats[c]?.[2]||'#e7ebdf'),borderColor:'#fafbf8',borderWidth:5,borderRadius:7,hoverOffset:3}]},options:{responsive:true,maintainAspectRatio:false,cutout:'78%',plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>`${ctx.label}: ${hours(ctx.raw)}`}}}}}))}if($('#week-chart')){let ds=lastDays(7);charts.push(new Chart($('#week-chart'),{type:'bar',data:{labels:ds.map(d=>parseDate(d).toLocaleDateString(undefined,{weekday:'short'})),datasets:[{label:'Completed',data:ds.map(d=>events(d).filter(a=>state.done[a.key]).length),backgroundColor:'#8da27a',borderRadius:5,barThickness:17},{label:'Scheduled',data:ds.map(d=>events(d).length),backgroundColor:'#e4eadc',borderRadius:5,barThickness:17}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,boxHeight:7,font:{size:10}}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:9}}},y:{beginAtZero:true,ticks:{stepSize:1,font:{size:9}},grid:{color:'#eef1e9'},border:{display:false}}}}}))}if($('#trend-chart')){let ds=lastDays(30);charts.push(new Chart($('#trend-chart'),{type:'line',data:{labels:ds.map(d=>parseDate(d).toLocaleDateString(undefined,{month:'short',day:'numeric'})),datasets:[{label:'Completion rate',data:ds.map(d=>events(d).length?Math.round(completionRate(d)*100):null),borderColor:'#6f8c5e',backgroundColor:'#8da27a22',fill:true,tension:.35,pointRadius:2,spanGaps:true}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.raw+'% complete'}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:9},maxTicksLimit:8}},y:{min:0,max:100,ticks:{stepSize:25,font:{size:9},callback:v=>v+'%'},grid:{color:'#eef1e9'},border:{display:false}}}}}))}if($('#category-chart')){let totals={};lastDays(7).forEach(d=>Object.entries(dayAllocation(d)).forEach(([c,n])=>{if(c!=='Unplanned')totals[c]=(totals[c]||0)+n}));let entries=Object.entries(totals).sort((a,b)=>b[1]-a[1]);charts.push(new Chart($('#category-chart'),{type:'bar',data:{labels:entries.map(e=>e[0]),datasets:[{label:'Planned hours',data:entries.map(e=>Number((e[1]/60).toFixed(1))),backgroundColor:entries.map(e=>cats[e[0]][2]),borderRadius:5,barThickness:14}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.raw+'h planned'}}},scales:{x:{beginAtZero:true,grid:{color:'#eef1e9'},border:{display:false},ticks:{font:{size:9},callback:v=>v+'h'}},y:{grid:{display:false},border:{display:false},ticks:{font:{size:10}}}}}}))}}
function render(){charts.forEach(c=>c.destroy());charts=[];$('#main').innerHTML=({dashboard,calendar,timetable,activities:activitiesView,analytics,notifications,settings,help,admin}[view]||dashboard)();$('#breadcrumb').textContent={dashboard:'Overview',calendar:'Calendar',timetable:'My timetable',activities:'All activities',analytics:'Insights & analytics',notifications:'Notifications & email',help:'Help & support',admin:'Admin console',settings:'Preferences'}[view];$$('nav button,.dock button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#log-count').textContent=state.logs.length+(emailEntries?.length||0);$('#activity-count').textContent=state.activities.length;drawCharts();drawAdminCharts();const adminNav=document.querySelector('#nav-admin');if(adminNav)adminNav.hidden=!window.dayformIsAdmin;if(view==='activities')filterActivities();if(view==='notifications')loadEmailLog();scheduleStartReminders();if(view==='timetable')alignTimetable()}
function openForm(id,hour){const form=$('#activity-form'),existing=state.activities.find(a=>a.id===id);if(existing&&existing.repeat==='none'&&existing.date<today()){toast('Past activities are locked and can’t be edited.');return}form.reset();$('#form-error').textContent='';form.elements.date.min=existing?'':today();let a=state.activities.find(a=>a.id===id);$('#modal-title').textContent=a?'Edit or reschedule':'Plan an activity';form.elements.id.value=a?.id||'';form.elements.date.value=a?.date||selected;form.elements.start.value=a?.start||`${String(hour??9).padStart(2,'0')}:00`;form.elements.end.value=a?.end||`${String(((hour??9)+1)%24).padStart(2,'0')}:00`;if(a)for(const k of ['title','category','repeat','link','notes'])form.elements[k].value=a[k]||'';$('#activity-dialog').showModal()}
$('#activity-form').addEventListener('submit',e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.title=data.title.trim();if(!data.title){$('#form-error').textContent='Please give your activity a name.';return}if(data.link&&!/^https?:\/\//i.test(data.link)){$('#form-error').textContent='Use a meeting link starting with https:// or http://.';return}if(data.start===data.end){$('#form-error').textContent='End time must differ from the start time.';return}if(data.date<today()&&(!state.activities.some(a=>a.id===data.id)||state.activities.find(a=>a.id===data.id).date!==data.date)){$('#form-error').textContent='Past days are locked. Choose today or a future date.';return}let old=state.activities.find(a=>a.id===data.id);if(old){Object.assign(old,data);log('Rescheduled / edited',`${data.title}: ${data.date}, ${data.start}–${data.end}. Existing completion records were preserved.`)}else{data.id=crypto.randomUUID();state.activities.push(data);log('Activity added',`${data.title}: ${data.date}, ${data.start}–${data.end}`)}save();$('#activity-dialog').close();render();toast(old?'Activity updated. Repeat-series edits apply to all occurrences.':'A little intention added to your day.')});
$('#close-modal').onclick=()=>$('#activity-dialog').close();$('#dock-add').onclick=()=>openForm();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.view)go(d.view);if('add'in d)openForm();if(d.edit){$('#details-dialog')?.close();openForm(d.edit);}if(d.hour)openForm(null,Number(d.hour));if(d.delete){let a=state.activities.find(a=>a.id===d.delete);if(a&&confirm(`Delete “${a.title}”${a.repeat!=='none'?' and all its repeating occurrences':''}?`)){state.activities=state.activities.filter(x=>x.id!==a.id);Object.keys(state.done).filter(k=>k.startsWith(a.id+'@')).forEach(k=>delete state.done[k]);$('#details-dialog')?.close();log('Activity deleted',a.title);render();toast('Activity removed.')}}if(d.filter){filter=d.filter;render()}if(d.shift){selected=addDays(selected,Number(d.shift));render()}if(d.day){selected=d.day;go('dashboard')}if(d.duplicate){const a=state.activities.find(a=>a.id===d.duplicate);if(a){const copy={...a,id:crypto.randomUUID(),title:(a.title+' (copy)').slice(0,100)};state.activities.push(copy);log('Activity duplicated',`${copy.title}: ${copy.date}, ${copy.start}–${copy.end}`);render();toast('Duplicated. Edit the copy to reschedule it.')}}if(d.catFilter){activityCat=d.catFilter;$$('[data-cat-filter]').forEach(x=>x.classList.toggle('active',x.dataset.catFilter===activityCat));filterActivities()}if(b.id==='header-search')openSearch();if(b.id==='toggle-email'){state.emailReminders=!state.emailReminders;log(state.emailReminders?'Email turned on':'Email turned off',`8 PM email reminders ${state.emailReminders?'on':'off'} for ${window.dayformUser?.email||'your account email'}.`);render();toast(state.emailReminders?'8 PM emails on.':'8 PM emails off.')}if(b.id==='verify-email'){b.disabled=true;try{await window.dayformSendVerification();log('Verification email sent',`Sent to ${window.dayformUser?.email}. Open the link, then reload Dayform.`);toast('Verification email sent. Open the link, then reload.')}catch(err){toast(err.message);b.disabled=false}}if(b.id==='test-email')sendTestEmail(b);if(b.id==='test-notification')testNotification();if(b.id==='import-data')$('#import-file').click();if(b.id==='today'){selected=today();render()}if(b.id==='profile-verify'){b.disabled=true;try{await window.dayformSendVerification();$('#profile-message').textContent='Verification email sent. Check your inbox.'}catch(err){$('#profile-message').textContent=err.message;b.disabled=false}}if(b.id==='prev-month'||b.id==='next-month'){calendarMonth.setDate(1);calendarMonth.setMonth(calendarMonth.getMonth()+(b.id==='prev-month'?-1:1));render()}if(b.id==='month-today'){calendarMonth=parseDate(today());render()}if(b.id==='toggle-notifications')toggleNotifications();if(b.id==='export-data')download('dayform-backup.json',JSON.stringify(state,null,2),'application/json');if(b.id==='export-log')download('dayform-audit.json',JSON.stringify(state.logs,null,2),'application/json');if(b.id==='clear-samples'){let count=state.activities.filter(a=>a.notes==='Sample activity — make this day your own.').length;state.activities=state.activities.filter(a=>a.notes!=='Sample activity — make this day your own.');state.seed=false;log('Samples removed',`${count} sample activities removed.`);render();toast('Ready for your own rhythm.')}if(b.id==='export-calendar')exportCalendar()});
document.addEventListener('change',e=>{if(e.target.id==='import-file'&&e.target.files[0])importBackup(e.target.files[0]);if(e.target.id==='selected-date'&&e.target.value){selected=e.target.value;render()}if(e.target.dataset.complete){const key=e.target.dataset.complete,occ=occurrence(key);if(occ&&dayLocked(occ)){e.target.checked=!!state.done[key];toast('This day has ended and is locked. Past days can’t be edited.');return}if(state.done[key]){delete state.done[key];delete state.completionMeta[key];log('Completion undone',occurrence(key)?.title||key);render()}else{e.target.checked=false;openCompletion(key)}}});
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCalendar(){const stamp=d=>dateKey(d).replaceAll('-','')+'T'+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0')+'00',clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dayform//Planner//EN'];state.activities.forEach(a=>{let begin=new Date(a.date+'T'+a.start),finish=new Date(begin.getTime()+duration(a)*60000);lines.push('BEGIN:VEVENT','UID:'+a.id+'@dayform','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp(begin),'DTEND:'+stamp(finish),'SUMMARY:'+clean(a.title),'DESCRIPTION:'+clean(a.notes||''));if(a.link)lines.push('URL:'+a.link);if(a.repeat!=='none')lines.push('RRULE:FREQ='+a.repeat.toUpperCase());lines.push('END:VEVENT')});lines.push('END:VCALENDAR');download('dayform-calendar.ics',lines.join('\r\n'),'text/calendar')}

installActivityDialogs();document.addEventListener('change',e=>{if(e.target.name==='completedAt'||e.target.name==='estimated'){const custom=document.querySelector('#completion-content input[value=custom]');if(custom)custom.checked=true}});render();if(!window.dayformInitial)save();watchPermission();scheduleStartReminders();try{navigator.permissions?.query({name:'notifications'}).then(st=>{st.onchange=watchPermission}).catch(()=>{})}catch{}if(zoneChanged&&window.dayformInitial)save();let currentDay=today();setInterval(()=>{if(today()!==currentDay){if(selected===currentDay)selected=today();currentDay=today();toast('A new day has begun. Yesterday is now locked.')}watchPermission();scheduleStartReminders();if(!document.querySelector('dialog[open]')&&['dashboard','timetable','analytics'].includes(view))render()},60000);
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.addEventListener('pointermove',e=>{let banner=document.querySelector('.balance-banner');if(banner&&e.pointerType==='mouse'){let r=banner.getBoundingClientRect();let within=e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;banner.style.transform=within?`perspective(800px) rotateX(${(e.clientY-r.top-r.height/2)/40}deg) rotateY(${(e.clientX-r.left-r.width/2)/80}deg)`:'none'}})}

function profileSection(){const user=window.dayformUser||{};return `<section class="card profile-editor"><div><span class="heading-tag">YOUR ACCOUNT</span><h2>Hi, ${esc(user.displayName||'there')}.</h2><p>${esc(user.email||'')} · ${user.emailVerified?'Email verified':'Email not verified'}</p></div><form id="profile-form"><label>Display name<input name="displayName" value="${esc(user.displayName||'')}" maxlength="80" required autocomplete="name"></label><button class="primary">Save profile</button><button type="button" class="soft-button" id="profile-reset">Reset password</button>${user.emailVerified||!user.email?'':'<button type="button" class="soft-button" id="profile-verify">Verify email</button>'}<button type="button" class="soft-button" id="profile-logout">Sign out</button><p id="profile-message" role="status"></p></form></section>`}
function openDetails(key){const a=occurrence(key);if(!a)return;const done=state.done[key],locked=Date.now()<a.begin;$('#details-content').innerHTML=`<div class="modal-heading"><div><span class="heading-tag">${a.category} · ACTIVITY DETAILS</span><h2>${esc(a.title)}</h2></div><button class="icon-btn" data-close="details-dialog" aria-label="Close activity details">✕</button></div><dl class="details-list"><dt>Starts</dt><dd>${a.begin.toLocaleString()}</dd><dt>Ends</dt><dd>${a.finish.toLocaleString()}</dd><dt>Duration</dt><dd>${hours(duration(a))}</dd><dt>Repeat</dt><dd>${a.repeat==='none'?'Does not repeat':a.repeat}</dd><dt>Status</dt><dd>${dayLocked(a)?(done?'Completed · locked':'Missed · locked'):done?'Completed':locked?'Scheduled':Date.now()>a.finish?'Overdue':'In progress'}</dd>${done?`<dt>Completed at</dt><dd>${new Date(done).toLocaleString()}${state.completionMeta[key]?.estimated?' (estimated actual time)':''}</dd>`:''}<dt>Notes</dt><dd>${esc(a.notes||'No notes yet.')}</dd>${a.link?`<dt>Meeting</dt><dd><a href="${esc(a.link)}" target="_blank" rel="noopener">Join meeting ↗</a></dd>`:''}</dl><div class="detail-actions"><button class="primary" data-finish="${key}" ${locked||dayLocked(a)?'disabled':''}>${done?'Adjust completion time':'Did you finish? ✓'}</button><button class="soft-button" data-edit="${a.id}">Edit / reschedule</button><button class="soft-button" data-delete="${a.id}">Delete${a.repeat!=='none'?' series':''}</button><button class="soft-button" data-locate="${key}">View in timetable ↗</button></div><p class="form-hint">${dayLocked(a)?'This day has ended and is locked, so it can no longer be edited. ':''}${locked?'Completion unlocks at the scheduled start. ':''}${a.repeat!=='none'?'Editing or deleting applies to the whole series.':''}</p>`;$('#details-dialog').showModal()}
function localInput(d){return dateKey(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function openCompletion(key){const a=occurrence(key);if(!a)return;if(Date.now()<a.begin){toast('Completion unlocks at the scheduled start.');return}if(dayLocked(a)){toast('This day has ended and is locked. Past days can’t be edited.');return}$('#details-dialog').close();$('#completion-content').innerHTML=`<div class="modal-heading"><div><span class="heading-tag">A LITTLE CHECK-IN</span><h2>When did you finish?</h2><p>${esc(a.title)}</p></div><button type="button" class="icon-btn" data-close="completion-dialog" aria-label="Close completion">✕</button></div><input type="hidden" name="key" value="${key}"><label class="completion-option"><input type="radio" name="method" value="now" checked> Just now <small>Use the time you press Save</small></label><label class="completion-option"><input type="radio" name="method" value="ontime" ${a.finish>Date.now()?'disabled':''}> On time <small>${a.finish.toLocaleString()}</small></label><label class="completion-option"><input type="radio" name="method" value="custom"> At another time <small>Enter the actual time, or your best estimate</small></label><label>Completion date and time<input name="completedAt" type="datetime-local" min="${localInput(a.begin)}" max="${localInput(new Date())}" value="${localInput(new Date(state.done[key]||Date.now()))}"></label><label class="estimate-label"><input type="checkbox" name="estimated"> This is an estimate of when I finished</label><p class="form-hint">Only record completed work. A predicted future time does not mark the activity done.</p><p id="completion-error" role="alert"></p><button class="primary full" type="submit">Save completion ✓</button>`;$('#completion-dialog').showModal()}
function installActivityDialogs(){document.body.insertAdjacentHTML('beforeend','<dialog id="details-dialog" aria-label="Activity details"><div id="details-content"></div></dialog><dialog id="completion-dialog" aria-label="Record completion"><form id="completion-content"></form></dialog>');document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.details)openDetails(d.details);if(d.finish)openCompletion(d.finish);if(d.close)$('#'+d.close).close();if(d.slotDay){selected=d.slotDay;openForm(null,Number(d.slotHour))}if(d.weekDay){selected=d.weekDay;render()}if(d.locate){const a=occurrence(d.locate);if(a){$('#details-dialog').close();selected=a.day;go('timetable');scrollToHour(Number(a.start.split(':')[0]))}}if(b.id==='current-hour')scrollToHour(new Date().getHours());if(b.id==='profile-logout')window.dayformSignOut?.();if(b.id==='profile-reset'){b.disabled=true;try{await window.dayformResetPassword();$('#profile-message').textContent='Password reset email sent. Check your inbox.'}catch(err){$('#profile-message').textContent=err.message}finally{b.disabled=false}}});$('#completion-content').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),a=occurrence(f.get('key')),method=f.get('method'),time=method==='now'?new Date():method==='ontime'?a?.finish:new Date(f.get('completedAt')),error=completionError(a,time);if(error){$('#completion-error').textContent=error;return}state.done[a.key]=time.toISOString();state.completionMeta[a.key]={method,estimated:method==='custom'&&f.get('estimated')==='on',recordedAt:new Date().toISOString()};log('Completed',`${a.title} · occurrence ${a.day} · finished ${time.toLocaleString()}${state.completionMeta[a.key].estimated?' (estimated)':''}`);$('#completion-dialog').close();render();toast('Completion saved. Your analytics are updated.')});document.addEventListener('submit',async e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const name=new FormData(e.target).get('displayName').trim(),button=e.target.querySelector('button');if(!name){$('#profile-message').textContent='Please enter your name.';return}button.disabled=true;try{await window.dayformUpdateProfile(name);render();$('#profile-message').textContent='Profile updated.'}catch(err){$('#profile-message').textContent=err.message}finally{button.disabled=false}});}

function completionNudge(){const a=visibleEvents(today()).find(a=>!state.done[a.key]&&!dayLocked(a)&&a.finish<=Date.now()&&Date.now()-a.finish<7200000);return a?`<div class="balance-banner completion-nudge"><span>✓</span><div><h3>Did you finish ${esc(a.title)}?</h3><p>Scheduled to end at ${fmtTime(a.end)}. Record when you actually finished.</p></div><button class="soft-button" data-finish="${a.key}">Check in ↗</button></div>`:''}

function nowCard(){if(selected!==today())return '';const now=Date.now(),a=visibleEvents(today()).find(a=>a.begin<=now&&a.finish>now&&!state.done[a.key]);if(!a)return '';const pct=Math.round((now-a.begin)/(a.finish-a.begin)*100),left=Math.ceil((a.finish-now)/60000);return `<div class="now-card" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div class="now-info"><span class="heading-tag">HAPPENING NOW</span><h3>${esc(a.title)}</h3><div class="now-progress" role="progressbar" aria-label="Time elapsed" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><small>${fmtTime(a.start)} – ${fmtTime(a.end)} · ${left>=60?hours(left):left+' min'} left</small></div>${a.link?`<a class="soft-button" target="_blank" rel="noopener" href="${esc(a.link)}">Join ↗</a>`:''}<button class="soft-button" data-details="${a.key}">Details ↗</button></div>`}
function streaks(){const hit=d=>events(d).some(a=>state.done[a.key]);let cur=0,d=today(),best=0,run=0;if(!hit(d))d=addDays(d,-1);while(cur<366&&hit(d)){cur++;d=addDays(d,-1)}for(let i=365;i>=0;i--){if(hit(addDays(today(),-i)))best=Math.max(best,++run);else run=0}return {cur,best:Math.max(best,cur)}}
function insightStats(){const ev=lastDays(30).flatMap(events).filter(a=>a.finish<=Date.now()||state.done[a.key]),done=ev.filter(a=>state.done[a.key]),ontime=done.filter(a=>new Date(state.done[a.key])-a.finish<=900000).length,{cur,best}=streaks();return `<div class="stats">${[['Current streak','✧',cur+` <em>${cur===1?'day':'days'}</em>`,cur?'Keep the rhythm going':'Check in today to start a streak'],['Best streak','☆',best+` <em>${best===1?'day':'days'}</em>`,'Your longest run of check-in days'],['30-day completion','◉',(ev.length?Math.round(done.length/ev.length*100):0)+'%',`${done.length} of ${ev.length} due activities completed`],['On-time finishes','◷',(done.length?Math.round(ontime/done.length*100):0)+'%','Completed within 15 min of the scheduled end']].map(s=>`<div class="stat"><div class="stat-label">${s[0]}<span>${s[1]}</span></div><div class="stat-value">${s[2]}</div><div class="stat-note">${s[3]}</div></div>`).join('')}</div>`}
function weeklyMinutes(a){return duration(a)*({daily:7,weekly:1,monthly:12/52,yearly:1/52}[a.repeat]||0)}
function activitiesView(){const list=state.activities.slice().sort((a,b)=>a.title.localeCompare(b.title)),used=Object.keys(cats).filter(c=>list.some(a=>a.category===c));if(activityCat!=='all'&&!used.includes(activityCat))activityCat='all';return header('Everything you make time for.','Search, filter, duplicate and tidy up every activity and repeating routine.','ALL ACTIVITIES')+`<div class="toolbar activity-toolbar"><input id="activity-search" class="date-picker search-input" type="search" placeholder="Search name, notes or category…" aria-label="Search activities" value="${esc(activityQuery)}"><div class="chip-row">${['all',...used].map(c=>`<button class="chip ${activityCat===c?'active':''}" data-cat-filter="${c}">${c==='all'?'All':cats[c][0]+' '+c}</button>`).join('')}</div></div><section class="card"><div class="card-head"><div><h2>Your activities <span class="count-badge" id="activity-result-count"></span></h2><p>Repeating routines are edited as a whole series</p></div></div><div class="table-wrap"><table class="activities-table"><thead><tr><th>ACTIVITY</th><th>SCHEDULE</th><th>REPEATS</th><th>PER WEEK</th><th>CHECK-INS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(a=>`<tr data-activity-row data-cat="${a.category}" data-search="${esc((a.title+' '+(a.notes||'')+' '+a.category).toLowerCase())}"><td><div class="activity-cell" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div><button class="activity-title activity-title-button" data-edit="${a.id}">${esc(a.title)}</button><small>${a.category}${a.link?' · Meeting link':''}</small></div></div></td><td>${parseDate(a.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}<small>${fmtTime(a.start)} – ${fmtTime(a.end)} · ${hours(duration(a))}</small></td><td>${{none:'Once',daily:'Every day',weekly:'Every week',monthly:'Every month',yearly:'Every year'}[a.repeat]||a.repeat}</td><td>${a.repeat==='none'?'—':hours(weeklyMinutes(a))}</td><td>${Object.keys(state.done).filter(k=>k.startsWith(a.id+'@')).length}</td><td class="row-actions"><button class="mini-btn" data-edit="${a.id}" title="Edit or reschedule" aria-label="Edit ${esc(a.title)}">✎</button><button class="mini-btn" data-duplicate="${a.id}" title="Duplicate" aria-label="Duplicate ${esc(a.title)}">⧉</button><button class="mini-btn" data-delete="${a.id}" title="Delete" aria-label="Delete ${esc(a.title)}">×</button></td></tr>`).join('')}</tbody></table></div><div class="empty" id="activity-empty" ${list.length?'hidden':''}>${list.length?'No activities match your search.':'No activities yet.<br>Add one to start shaping your days.'}</div></section>`}
function filterActivities(){const q=activityQuery.toLowerCase().trim();let shown=0;$$('[data-activity-row]').forEach(r=>{const ok=(activityCat==='all'||r.dataset.cat===activityCat)&&r.dataset.search.includes(q);r.hidden=!ok;if(ok)shown++});if($('#activity-result-count'))$('#activity-result-count').textContent=`${shown} of ${state.activities.length}`;if($('#activity-empty')&&state.activities.length)$('#activity-empty').hidden=shown>0}
function openSearch(){if(view!=='activities')go('activities');$('#activity-search')?.focus()}
function permission(){return 'Notification'in window?Notification.permission:'unsupported'}
function notificationsOn(){return state.reminders&&permission()==='granted'}
function upcomingStarts(){const now=Date.now();return [...events(today()),...events(addDays(today(),1))].filter(a=>!state.done[a.key]&&a.begin>now).sort((a,b)=>a.begin-b.begin)}
// Sends each start reminder once, NOTIFY_LEAD before the start. Sent keys are saved so a reload doesn't repeat them.
function checkStartReminders(){if(!notificationsOn())return;const now=Date.now(),keep=addDays(today(),-1);state.notified=(state.notified||[]).filter(k=>k.slice(k.lastIndexOf('@')+1)>=keep);for(const a of upcomingStarts()){const until=a.begin-now;if(until>NOTIFY_LEAD||state.notified.includes(a.key))continue;state.notified.push(a.key);const mins=Math.max(1,Math.round(until/60000));try{const n=new Notification(`In ${mins} min: ${a.title}`,{body:`${fmtTime(a.start)} – ${fmtTime(a.end)} · ${a.category}${a.link?' · Meeting link in Dayform':''}`,tag:'dayform-start-'+a.key});n.onclick=()=>{window.focus();openDetails(a.key);n.close?.()};log('Notification sent',`“${a.title}” starts at ${fmtTime(a.start)} on ${a.day} (${mins} min notice).`)}catch(err){log('Notification failed',`“${a.title}”: ${err.message}`)}}}
// A timer is set for the exact moment of the next reminder; the minute interval is a fallback.
function scheduleStartReminders(){clearTimeout(startTimer);checkStartReminders();if(!notificationsOn())return;const next=upcomingStarts().find(a=>a.begin-NOTIFY_LEAD>Date.now()&&!(state.notified||[]).includes(a.key));if(next)startTimer=setTimeout(scheduleStartReminders,Math.min(next.begin-NOTIFY_LEAD-Date.now(),2147483000))}
function watchPermission(){if(state.reminders&&permission()!=='granted'){state.reminders=false;clearTimeout(startTimer);log('Notifications turned off',`The browser permission is now “${permission()}”, so notifications were switched off.`);if(['notifications','settings'].includes(view))render()}}
async function toggleNotifications(){if(state.reminders){state.reminders=false;clearTimeout(startTimer);log('Notifications turned off','Browser notifications before activities are off.');render();toast('Notifications turned off.');return}
const before=permission();if(before==='unsupported'){log('Notifications unavailable','This browser does not support notifications.');toast('This browser does not support notifications.');return}
if(before==='denied'){log('Notifications blocked','The browser blocks notifications for this site. Allow them in the browser’s site settings, then turn on again.');render();toast('Blocked by your browser. Allow notifications for this site in its settings.');return}
let p=before;if(p==='default'){p=await Notification.requestPermission();log({granted:'Permission allowed',denied:'Permission denied'}[p]||'Permission dismissed',`Browser notification permission: ${p}.`)}
if(p==='granted'){state.reminders=true;log('Notifications turned on','You’ll be notified 10 minutes before each activity starts while Dayform is open.');scheduleStartReminders();toast('Notifications on. You’ll get a heads-up 10 minutes before each activity.')}else toast(p==='denied'?'Notifications blocked. You can allow them later in browser settings.':'No permission given. Notifications stay off.');render()}
function nextReminderText(){if(!notificationsOn())return '—';const a=upcomingStarts().find(a=>!(state.notified||[]).includes(a.key));if(!a)return 'Nothing coming up';const at=new Date(Math.max(Date.now(),a.begin-NOTIFY_LEAD));return `${esc(a.title)} · at ${at.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}${a.day!==today()?' tomorrow':''}`}
function notificationControls(){const u=window.dayformUser||{},p=permission(),on=notificationsOn(),mail=state.emailReminders&&u.emailVerified;return `<div class="channel-grid"><section class="card channel-card"><div class="channel-head"><span class="channel-icon">♧</span><div><span class="heading-tag">BROWSER NOTIFICATIONS</span><h2>10 minutes before each activity</h2></div><span class="status-pill ${on?'on':''}">${on?'On':'Off'}</span></div><p>${!state.reminders?'Off. Turn on to get a heads-up 10 minutes before each activity starts.':on?'On while Dayform is open in this browser. Closed tabs can’t show notifications.':'On, but the browser hasn’t granted permission.'}</p><dl class="channel-meta"><dt>Permission</dt><dd>${{granted:'Allowed',denied:'Blocked in browser settings',default:'Not asked yet',unsupported:'Not supported'}[p]}</dd><dt>Next</dt><dd>${nextReminderText()}</dd></dl><div class="channel-actions"><button class="${state.reminders?'soft-button':'primary'}" id="toggle-notifications">${state.reminders?'Turn off':'Turn on'}</button><button class="soft-button" id="test-notification" ${p==='granted'?'':'disabled'}>Send test</button></div></section><section class="card channel-card"><div class="channel-head"><span class="channel-icon">✉</span><div><span class="heading-tag">EMAIL</span><h2>Every day at 8 PM</h2></div><span class="status-pill ${mail?'on':''}">${mail?'On':state.emailReminders?'Paused':'Off'}</span></div><p>${emailStatus()}</p><dl class="channel-meta"><dt>Sends to</dt><dd>${esc(u.email||'—')}</dd><dt>Last sent</dt><dd id="email-last">${emailEntries?esc(lastEmailText()):'Loading…'}</dd></dl><div class="channel-actions"><button class="${state.emailReminders?'soft-button':'primary'}" id="toggle-email">${state.emailReminders?'Turn off':'Turn on'}</button><button class="soft-button" id="test-email" ${mail?'':'disabled'}>Send test email</button>${u.emailVerified||!u.email?'':'<button class="soft-button" id="verify-email">Verify email</button>'}</div></section></div>`}
function lastEmailText(){const e=(emailEntries||[]).find(e=>e.type!=='failed');return e?`${new Date(e.at).toLocaleString()}${e.type==='test'?' (test)':''}`:'Not yet'}
function auditRows(){const rows=[...state.logs.map(l=>({at:l.at,type:l.type,message:l.message})),...(emailEntries||[]).map(e=>({at:e.at,type:e.type==='failed'?'Email failed':e.type==='test'?'Test email sent':'Email sent',message:e.type==='failed'?`8 PM reminder to ${e.to||'your email'} failed: ${e.error||'unknown error'}. It will retry within the hour.`:`${e.type==='test'?'Test of the 8 PM reminder':'8 PM reminder'} to ${e.to} · ${e.pending} of ${e.total} activities unchecked for ${e.date}.`}))].sort((a,b)=>b.at.localeCompare(a.at));return rows.map(l=>`<tr><td>${new Date(l.at).toLocaleString()}</td><td>${esc(l.type)}</td><td>${esc(l.message)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No events yet. Permissions, changes, notifications and emails will appear here.</td></tr>'}
// Backups are validated field by field so a malformed file cannot corrupt the saved planner.
async function importBackup(file){const input=$('#import-file');try{if(file.size>900000)throw Error('This file is too large to be a Dayform backup.');const data=JSON.parse(await file.text()),time=/^([01]\d|2[0-3]):[0-5]\d$/,day=/^\d{4}-\d{2}-\d{2}$/;if(!data||!Array.isArray(data.activities)||typeof data.done!=='object'||!data.done)throw Error('This file is not a Dayform backup.');const activities=data.activities.map(a=>({id:String(a.id||crypto.randomUUID()),title:String(a.title||'').slice(0,100),category:cats[a.category]?a.category:'Custom',date:String(a.date),start:String(a.start),end:String(a.end),repeat:['none','daily','weekly','monthly','yearly'].includes(a.repeat)?a.repeat:'none',link:/^https?:\/\//i.test(a.link||'')?String(a.link):'',notes:String(a.notes||'').slice(0,2000)}));if(activities.some(a=>!a.title||!day.test(a.date)||!time.test(a.start)||!time.test(a.end)))throw Error('Some activities in this backup have missing names, dates or times.');const done=Object.fromEntries(Object.entries(data.done).filter(([k,v])=>typeof v==='string'&&Number.isFinite(Date.parse(v))));if(!confirm(`Replace your planner with this backup (${activities.length} activities, ${Object.keys(done).length} check-ins)? Export a backup first if you want to keep your current plans.`))return;state.activities=activities;state.done=done;state.completionMeta=data.completionMeta&&typeof data.completionMeta==='object'?Object.fromEntries(Object.entries(data.completionMeta).filter(([k])=>done[k])):{};state.seed=false;log('Backup restored',`${activities.length} activities and ${Object.keys(done).length} check-ins imported from ${file.name}.`);render();toast('Backup restored.')}catch(err){toast(err instanceof SyntaxError?'That file is not valid JSON.':err.message)}finally{input&&(input.value='')}}
window.addEventListener('popstate',()=>{const v=location.pathname.slice(1);view=VIEWS.includes(v)?v:'dashboard';render()});
document.addEventListener('input',e=>{if(e.target.id==='activity-search'){activityQuery=e.target.value;filterActivities()}});
document.addEventListener('click',e=>{const dialog=e.target;if(dialog.tagName!=='DIALOG'||!dialog.open)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
document.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey||document.querySelector('dialog[open]')||e.target.closest?.('input,textarea,select,[contenteditable]'))return;const k=e.key.toLowerCase();if(k==='n'){e.preventDefault();openForm()}else if(k==='/'){e.preventDefault();openSearch()}else if(k==='t'){selected=today();calendarMonth=parseDate(today());render()}else if((k==='arrowleft'||k==='arrowright')&&['dashboard','timetable','analytics'].includes(view)){e.preventDefault();selected=addDays(selected,k==='arrowleft'?-1:1);render()}else if(/^[1-7]$/.test(k))go(VIEWS[Number(k)-1])});
function scrollToHour(h){const row=$('#hour-'+h);if(!row)return;const col=$$('.week-table thead th').findIndex(th=>th.classList.contains('selected-day'));(row.children[col]||row).scrollIntoView({block:'center',inline:'nearest',behavior:'smooth'})}
// The planner may still be hidden behind the sign-in screen on first render, so wait until it has a width.
function alignTimetable(tries=20){const day=$('.week-table thead .selected-day'),scroller=$('.week-scroll');if(!day||!scroller)return;if(!scroller.clientWidth){if(tries)setTimeout(()=>alignTimetable(tries-1),100);return}scroller.scrollLeft=day.offsetLeft-$('.week-table thead th').offsetWidth}
function emailStatus(){const u=window.dayformUser||{};if(!state.emailReminders)return 'Off. Turn on to get a nightly email listing activities you haven’t checked in.';if(!u.emailVerified)return `On, but paused: verify ${esc(u.email||'your email')} to receive reminders.`;return `On. Sent to ${esc(u.email)} at 8 PM (${esc(state.timezone)}) when activities are still unchecked. Days lock at midnight.`}
async function loadEmailLog(){try{const log=await window.dayformEmailLog?.();emailEntries=log?.entries||[]}catch(err){emailEntries=[];if($('#email-last'))$('#email-last').textContent='Couldn’t load: '+err.message;return}if($('#audit-log'))$('#audit-log').innerHTML=auditRows();if($('#email-last'))$('#email-last').textContent=lastEmailText();$('#log-count').textContent=state.logs.length+emailEntries.length}
async function sendTestEmail(b){b.disabled=true;try{const token=await window.dayformIdToken?.();const r=await fetch('/api/test-email',{method:'POST',headers:{Authorization:'Bearer '+token}});const body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body.error||(r.status===404?'The email server isn’t deployed here. Deploy to Vercel with the email settings first.':'Email could not be sent.'));toast('Test email sent to '+body.to+'.');loadEmailLog()}catch(err){toast(err.message)}finally{b.disabled=false}}
async function testNotification(){if(!('Notification'in window)){toast('This browser does not support notifications.');return}const p=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(p!=='granted'){toast('Notifications are blocked. Allow them in your browser’s site settings.');log('Test notification blocked',`Browser notification permission: ${p}.`);return}try{new Notification('Dayform test notification',{body:'Notifications are working on this device.',tag:'dayform-test'});toast('Test notification sent.');log('Test notification sent','A test notification was shown by this browser.')}catch(err){toast('This browser only allows notifications from an installed app.');log('Notification failed',err.message)}}
function tickClock(){const el=$('#live-clock');if(!el)return;const now=new Date();el.dateTime=now.toISOString();el.innerHTML=`<span class="clock-date">${now.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} · </span>${now.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',second:'2-digit'})}`;el.title=`Local time · ${state.timezone}`}
tickClock();setInterval(tickClock,1000);

// ---- Help & support (users) and admin messages ----
function fmtWhen(iso){return iso?new Date(iso).toLocaleString(undefined,{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):''}
function ticketThread(t,asAdmin){return `<div class="thread"><div class="reply user"><b>${esc(t.name||t.email)}</b><small>${fmtWhen(t.createdAt)}</small><p>${esc(t.message)}</p></div>${(t.replies||[]).map(r=>`<div class="reply ${r.by}"><b>${esc(r.name)}</b><small>${fmtWhen(r.at)}</small><p>${esc(r.text)}</p></div>`).join('')}</div><form class="reply-form" data-ticket-reply="${t.id}" data-as-admin="${asAdmin?1:''}"><label class="sr-only" for="reply-${t.id}">Reply</label><textarea id="reply-${t.id}" name="text" rows="2" maxlength="4000" required placeholder="${asAdmin?'Reply to the user…':'Add a reply…'}"></textarea>${asAdmin?`<select name="status" aria-label="Status after reply"><option value="">Keep status</option><option value="in_progress">Mark in progress</option><option value="resolved">Mark resolved</option><option value="closed">Mark closed</option></select>`:''}<button class="primary">Send reply</button></form>`}
function help(){if(myTicketList===null)loadMyTickets();return header('We’re here to help.','Raise a ticket and follow the conversation here. You’ll usually hear back within a day.','HELP & SUPPORT')+`<div class="help-grid"><section class="card help-form-card"><div class="card-head"><div><h2>Raise a ticket</h2><p>Tell us what you need</p></div></div><form id="ticket-form" class="padded-form"><label>Topic<select name="category">${['help','bug','account','feedback'].map(c=>`<option value="${c}">${ticketCats[c]}</option>`).join('')}</select></label><label>Subject<input name="subject" maxlength="120" required placeholder="A short summary"></label><label>Message<textarea name="message" rows="5" maxlength="4000" required placeholder="What happened, and what did you expect?"></textarea></label><p id="ticket-message" role="status"></p><button class="primary full">Send ticket ↗</button></form></section><section class="card"><div class="card-head"><div><h2>Your tickets <span class="count-badge">${myTicketList?myTicketList.length:'…'}</span></h2><p>Open one to read replies or respond</p></div></div><div class="ticket-list">${myTicketList===null?'<div class="empty">Loading your tickets…</div>':myTicketList.map(t=>`<article class="ticket ${openTicketId===t.id?'open':''}"><button class="ticket-summary" data-toggle-ticket="${t.id}" aria-expanded="${openTicketId===t.id}"><span><b>${esc(t.subject)}</b><small>${ticketCats[t.category]||t.category} · ${fmtWhen(t.createdAt)} · ${(t.replies||[]).length} repl${(t.replies||[]).length===1?'y':'ies'}</small></span><span class="ticket-status ${t.status}">${ticketLabel[t.status]}</span></button>${openTicketId===t.id?ticketThread(t,false):''}</article>`).join('')||'<div class="empty">No tickets yet.</div>'}</div></section></div>`}
async function loadMyTickets(){try{myTicketList=await cloud()?.myTickets()||[]}catch(e){myTicketList=[];toast('Couldn’t load tickets: '+(e.code||e.message))}if(view==='help')render()}
async function loadInbox(){try{inboxList=await cloud()?.inbox()||[]}catch{inboxList=[]}const unread=inboxList.filter(m=>!m.read).length;const badge=$('#inbox-count');if(badge){badge.textContent=unread||'';badge.hidden=!unread}if(view==='notifications'&&$('#inbox-list'))$('#inbox-list').innerHTML=inboxRows()}
function inboxRows(){return (inboxList||[]).map(m=>`<article class="inbox-item ${m.read?'':'unread'}"><div><b>${esc(m.title)}</b><small>${esc(m.from)} · ${fmtWhen(m.createdAt)}</small><p>${esc(m.body)}</p></div>${m.read?'':`<button class="soft-button" data-mark-read="${m.id}">Mark read</button>`}</article>`).join('')||'<div class="empty">No messages from Dayform.</div>'}
function inboxCard(){return `<section class="card" style="margin-bottom:22px"><div class="card-head"><div><h2>Messages from Dayform</h2><p>Notes from the Dayform team about your account</p></div></div><div id="inbox-list" class="inbox-list">${inboxList===null?'<div class="empty">Loading…</div>':inboxRows()}</div></section>`}

// ---- Admin console ----
async function loadAdmin(force){if(adminLoading||(adminData&&!force))return;adminLoading=true;try{const c=cloud();const [users,tickets,stats,audit]=await Promise.all([c.listUsers(),c.listTickets(),c.emailStats(),c.auditLog()]);const logs=await c.emailLogs(users.map(u=>u.id));adminData={users,tickets,stats,audit,logs,at:new Date()}}catch(e){adminData={error:e.code||e.message}}adminLoading=false;if(view==='admin')render()}
function restrictedNow(u){return u.status==='blocked'||(u.status==='suspended'&&u.suspendedUntil&&Date.parse(u.suspendedUntil)>Date.now())}
function userStatus(u){return u.status==='blocked'?'Blocked':restrictedNow(u)?'Suspended':'Active'}
function adminStats(){const {users,tickets,stats}=adminData,s=Object.fromEntries(stats.map(x=>[x.id,x])),sum=(n,k)=>Array.from({length:n},(_,i)=>s[daysAgo(i)]?.[k]||0).reduce((a,b)=>a+b,0);return {total:users.length,newWeek:users.filter(u=>u.createdAt&&u.createdAt.slice(0,10)>=daysAgo(6)).length,activeToday:users.filter(u=>u.lastActiveAt&&dayIso(new Date(u.lastActiveAt))===today()).length,blocked:users.filter(u=>u.status==='blocked').length,suspended:users.filter(u=>u.status==='suspended'&&restrictedNow(u)).length,verified:users.filter(u=>u.emailVerified).length,notifOn:users.filter(u=>u.notificationsOn).length,emailOn:users.filter(u=>u.emailOn!==false).length,sentToday:sum(1,'sent'),sent7:sum(7,'sent'),sent30:sum(30,'sent'),failed30:sum(30,'failed'),open:tickets.filter(t=>t.status==='open').length,progress:tickets.filter(t=>t.status==='in_progress').length,resolved:tickets.filter(t=>['resolved','closed'].includes(t.status)).length}}
function statTiles(list){return `<div class="stats">${list.map(([l,i,v,n])=>`<div class="stat"><div class="stat-label">${l}<span>${i}</span></div><div class="stat-value">${v}</div><div class="stat-note">${n}</div></div>`).join('')}</div>`}
function admin(){if(!window.dayformIsAdmin)return header('Admins only.','This page is only available to Dayform administrators.','ADMIN');if(!adminData){loadAdmin();return header('Admin console','Loading users, tickets and email activity…','ADMIN')+'<div class="empty">Loading…</div>'}if(adminData.error)return header('Admin console','Something went wrong loading admin data.','ADMIN')+`<div class="card empty">Couldn’t load: ${esc(adminData.error)}.<br>Check that the latest Firestore rules are published and your admin access is set.<br><button class="soft-button" data-admin-refresh>Try again</button></div>`;const tabs=[['overview','Insights'],['users','Users'],['tickets','Tickets'],['emails','Emails'],['audit','Admin log']],open=adminData.tickets.filter(t=>t.status==='open').length;return header('Admin console',`Signed in as ${esc(window.dayformUser?.email)} · Data loaded ${adminData.at.toLocaleTimeString()}`,'ADMIN')+`<div class="toolbar admin-tabs" role="tablist">${tabs.map(([k,t])=>`<button role="tab" aria-selected="${adminTab===k}" class="chip ${adminTab===k?'active':''}" data-admin-tab="${k}">${t}${k==='tickets'&&open?` <i class="tab-badge">${open}</i>`:''}</button>`).join('')}<button class="soft-button right-btn" data-admin-refresh>↻ Refresh</button></div>`+({overview:adminOverview,users:adminUsers,tickets:adminTickets,emails:adminEmails,audit:adminAudit}[adminTab])()}
function adminOverview(){const s=adminStats(),pct=(a,b)=>b?Math.round(a/b*100)+'%':'—';return statTiles([['Users','◎',s.total,`${s.newWeek} joined in the last 7 days`],['Active today','◷',s.activeToday,`${pct(s.activeToday,s.total)} of all users`],['Emails sent today','✉',s.sentToday,`${s.sent7} in 7 days · ${s.sent30} in 30 days`],['Open tickets','?',s.open,`${s.progress} in progress · ${s.resolved} resolved`]])+statTiles([['Notifications on','♧',s.notifOn,`${s.total-s.notifOn} turned off · ${pct(s.notifOn,s.total)} on`],['8 PM email on','✉',s.emailOn,`${s.total-s.emailOn} turned off · ${pct(s.emailOn,s.total)} on`],['Verified emails','✓',s.verified,`${s.total-s.verified} not verified (no emails)`],['Restricted','⦸',s.blocked+s.suspended,`${s.blocked} blocked · ${s.suspended} suspended`]])+`<div class="analytics-grid"><section class="card"><div class="card-head"><div><h2>Emails per day</h2><p>8 PM reminders sent and failed · Last 30 days · ${s.failed30} failed</p></div></div><div class="bar-chart"><canvas id="admin-email-chart" role="img" aria-label="Emails sent per day"></canvas></div></section><section class="card"><div class="card-head"><div><h2>New users</h2><p>Sign-ups per day · Last 30 days</p></div></div><div class="bar-chart"><canvas id="admin-signup-chart" role="img" aria-label="Sign-ups per day"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Channels</h2><p>How users get reminded</p></div></div><div class="bar-chart"><canvas id="admin-channel-chart" role="img" aria-label="Notification and email settings"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Most emailed</h2><p>Users by reminder emails received</p></div><button class="text-button" data-admin-tab="users">All users ↗</button></div><div class="table-wrap"><table><thead><tr><th>USER</th><th>EMAILS</th><th>LAST EMAIL</th></tr></thead><tbody>${adminData.users.slice().sort((a,b)=>(b.emailsSent||0)-(a.emailsSent||0)).slice(0,6).map(u=>`<tr><td>${esc(u.displayName||u.email)}<small>${esc(u.email)}</small></td><td>${u.emailsSent||0}</td><td>${u.lastEmailAt?fmtWhen(u.lastEmailAt):'—'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No users yet.</td></tr>'}</tbody></table></div></section></div>`}
function adminUsers(){const q=adminUserQuery.toLowerCase(),list=adminData.users.filter(u=>(adminUserStatus==='all'||userStatus(u).toLowerCase()===adminUserStatus)&&(`${u.displayName} ${u.email}`.toLowerCase().includes(q))).sort((a,b)=>(b.lastActiveAt||'').localeCompare(a.lastActiveAt||''));return `<div class="toolbar activity-toolbar"><input id="admin-user-search" class="date-picker search-input" type="search" placeholder="Search name or email…" aria-label="Search users" value="${esc(adminUserQuery)}"><div class="chip-row">${['all','active','suspended','blocked'].map(k=>`<button class="chip ${adminUserStatus===k?'active':''}" data-admin-user-status="${k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div></div><section class="card"><div class="card-head"><div><h2>All users <span class="count-badge">${list.length} of ${adminData.users.length}</span></h2><p>Profile summaries update while users are active</p></div></div><div class="table-wrap"><table class="admin-users"><thead><tr><th>USER</th><th>JOINED</th><th>LAST ACTIVE</th><th>ACTIVITIES</th><th>NOTIFICATIONS</th><th>EMAIL</th><th>EMAILS SENT</th><th>STATUS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(u=>`<tr><td><button class="link-button" data-admin-user="${u.id}">${esc(u.displayName||'(no name)')}</button><small>${esc(u.email)} ${u.emailVerified?'· ✓ verified':'· not verified'}</small></td><td>${u.createdAt?new Date(u.createdAt).toLocaleDateString():'—'}</td><td>${u.lastActiveAt?fmtWhen(u.lastActiveAt):'—'}</td><td>${u.activityCount??0}</td><td>${onOff(u.notificationsOn)}</td><td>${onOff(u.emailOn!==false)}</td><td>${u.emailsSent||0}</td><td><span class="status-tag ${userStatus(u).toLowerCase()}">${userStatus(u)}</span>${restrictedNow(u)&&u.status==='suspended'?`<small>until ${new Date(u.suspendedUntil).toLocaleDateString()}</small>`:''}</td><td class="row-actions">${userActions(u)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No users match.</td></tr>'}</tbody></table></div></section>`}
function onOff(v){return `<span class="onoff ${v?'on':''}">${v?'On':'Off'}</span>`}
function userActions(u){const self=u.email===window.dayformUser?.email;return `<button class="mini-btn" data-admin-user="${u.id}" title="View profile" aria-label="View ${esc(u.email)}">◉</button><button class="mini-btn" data-admin-message="${u.id}" title="Send message" aria-label="Message ${esc(u.email)}">✉</button>${self?'':restrictedNow(u)?`<button class="mini-btn" data-admin-restore="${u.id}" title="Restore access" aria-label="Restore ${esc(u.email)}">↺</button>`:`<button class="mini-btn" data-admin-suspend="${u.id}" title="Suspend" aria-label="Suspend ${esc(u.email)}">⏸</button><button class="mini-btn danger" data-admin-block="${u.id}" title="Block" aria-label="Block ${esc(u.email)}">⦸</button>`}`}
function adminTickets(){const list=adminData.tickets.filter(t=>adminTicketStatus==='all'||t.status===adminTicketStatus),sel=adminData.tickets.find(t=>t.id===adminTicketId),owner=sel&&adminData.users.find(u=>u.id===sel.uid);return `<div class="toolbar"><div class="chip-row">${['open','in_progress','resolved','closed','all'].map(k=>`<button class="chip ${adminTicketStatus===k?'active':''}" data-admin-ticket-status="${k}">${k==='all'?'All':ticketLabel[k]} <i class="tab-badge muted-badge">${k==='all'?adminData.tickets.length:adminData.tickets.filter(t=>t.status===k).length}</i></button>`).join('')}</div></div><div class="admin-ticket-grid"><section class="card"><div class="ticket-list">${list.map(t=>`<button class="ticket-summary ${t.id===adminTicketId?'selected':''}" data-admin-ticket="${t.id}"><span><b>${esc(t.subject)}</b><small>${esc(t.email)} · ${ticketCats[t.category]||t.category} · ${fmtWhen(t.updatedAt)}</small></span><span class="ticket-status ${t.status}">${ticketLabel[t.status]}</span></button>`).join('')||'<div class="empty">No tickets here.</div>'}</div></section><section class="card ticket-detail">${sel?`<div class="card-head"><div><span class="heading-tag">${(ticketCats[sel.category]||sel.category).toUpperCase()}</span><h2>${esc(sel.subject)}</h2><p>${esc(sel.email)} · opened ${fmtWhen(sel.createdAt)}${owner?` · account ${userStatus(owner).toLowerCase()}`:''}</p></div><select data-admin-ticket-set="${sel.id}" aria-label="Ticket status">${Object.entries(ticketLabel).map(([k,v])=>`<option value="${k}" ${sel.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="ticket-body">${owner&&restrictedNow(owner)?`<div class="balance-banner"><span>⦸</span><div><h3>This user is ${userStatus(owner).toLowerCase()}.</h3><p>${esc(owner.statusReason||'No reason recorded.')}</p></div><button class="primary" data-admin-restore="${owner.id}">Restore access</button></div>`:''}${owner?`<button class="text-button" data-admin-user="${owner.id}">View user profile ↗</button>`:''}${ticketThread(sel,true)}</div>`:'<div class="empty">Choose a ticket to read and reply.</div>'}</section></div>`}
function adminEmailRows(){return Object.entries(adminData.logs).flatMap(([uid,l])=>(l.entries||[]).map(e=>({...e,uid}))).sort((a,b)=>b.at.localeCompare(a.at))}
function adminEmails(){const s=Object.fromEntries(adminData.stats.map(x=>[x.id,x])),days=Array.from({length:14},(_,i)=>daysAgo(i)),rows=adminEmailRows();return `<div class="analytics-grid"><section class="card"><div class="card-head"><div><h2>Per day</h2><p>Last 14 days</p></div></div><div class="table-wrap"><table><thead><tr><th>DAY</th><th>SENT</th><th>FAILED</th><th>TESTS</th></tr></thead><tbody>${days.map(d=>`<tr><td>${parseDate(d).toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})}</td><td>${s[d]?.sent||0}</td><td>${s[d]?.failed||0}</td><td>${s[d]?.test||0}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h2>Per user</h2><p>Reminder emails received</p></div></div><div class="table-wrap"><table><thead><tr><th>USER</th><th>EMAILS</th><th>EMAIL</th></tr></thead><tbody>${adminData.users.slice().sort((a,b)=>(b.emailsSent||0)-(a.emailsSent||0)).map(u=>`<tr><td>${esc(u.email)}</td><td>${u.emailsSent||0}</td><td>${onOff(u.emailOn!==false)}${u.emailVerified?'':' <small>not verified</small>'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No users yet.</td></tr>'}</tbody></table></div></section><section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Recent emails <span class="count-badge">${rows.length}</span></h2><p>Every reminder, test and failure (latest 60 per user)</p></div></div><div class="table-wrap"><table><thead><tr><th>SENT</th><th>TO</th><th>TYPE</th><th>FOR DAY</th><th>DETAILS</th></tr></thead><tbody>${rows.slice(0,200).map(e=>`<tr><td>${new Date(e.at).toLocaleString()}</td><td>${esc(e.to)}</td><td><span class="status-tag ${e.type==='failed'?'blocked':'active'}">${e.type==='failed'?'Failed':e.type==='test'?'Test':'8 PM reminder'}</span></td><td>${esc(e.date)}</td><td>${e.type==='failed'?esc(e.error):`${e.pending} of ${e.total} unchecked`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No emails sent yet.</td></tr>'}</tbody></table></div></section></div>`}
function adminAudit(){return `<section class="card"><div class="card-head"><div><h2>Admin log</h2><p>Every block, suspension, restore, message and ticket change</p></div></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>ADMIN</th><th>ACTION</th><th>TARGET</th><th>DETAILS</th></tr></thead><tbody>${adminData.audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.by)}</td><td>${esc(a.action)}</td><td>${esc(a.target)}</td><td>${esc(a.details)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No admin actions yet.</td></tr>'}</tbody></table></div></section>`}
function drawAdminCharts(){if(typeof Chart==='undefined'||view!=='admin'||!adminData||adminData.error||adminTab!=='overview')return;const s=Object.fromEntries(adminData.stats.map(x=>[x.id,x])),ds=Array.from({length:30},(_,i)=>daysAgo(29-i)),labels=ds.map(d=>parseDate(d).toLocaleDateString(undefined,{day:'numeric',month:'short'})),axis={x:{grid:{display:false},border:{display:false},ticks:{font:{size:9},maxTicksLimit:8}},y:{beginAtZero:true,ticks:{precision:0,font:{size:9}},grid:{color:'#eef1e9'},border:{display:false}}},legend={position:'bottom',labels:{usePointStyle:true,boxWidth:7,boxHeight:7,font:{size:10}}};
if($('#admin-email-chart'))charts.push(new Chart($('#admin-email-chart'),{type:'bar',data:{labels,datasets:[{label:'Sent',data:ds.map(d=>s[d]?.sent||0),backgroundColor:'#8da27a',borderRadius:4},{label:'Failed',data:ds.map(d=>s[d]?.failed||0),backgroundColor:'#c9a091',borderRadius:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend},scales:{...axis,x:{...axis.x,stacked:true},y:{...axis.y,stacked:true}}}}));
if($('#admin-signup-chart')){const by={};adminData.users.forEach(u=>{if(u.createdAt){const d=dayIso(new Date(u.createdAt));by[d]=(by[d]||0)+1}});charts.push(new Chart($('#admin-signup-chart'),{type:'line',data:{labels,datasets:[{label:'Sign-ups',data:ds.map(d=>by[d]||0),borderColor:'#6f8c5e',backgroundColor:'#8da27a22',fill:true,tension:.35,pointRadius:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:axis}}))}
if($('#admin-channel-chart')){const st=adminStats();charts.push(new Chart($('#admin-channel-chart'),{type:'bar',data:{labels:['Notifications','8 PM email','Verified email'],datasets:[{label:'On',data:[st.notifOn,st.emailOn,st.verified],backgroundColor:'#8da27a',borderRadius:4},{label:'Off',data:[st.total-st.notifOn,st.total-st.emailOn,st.total-st.verified],backgroundColor:'#e4eadc',borderRadius:4}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend},scales:{x:{...axis.y,stacked:true},y:{grid:{display:false},border:{display:false},stacked:true,ticks:{font:{size:10}}}}}}))}}
async function adminUserDialog(uid){const u=adminData.users.find(x=>x.id===uid);if(!u)return;$('#admin-content').innerHTML=`<div class="modal-heading"><div><span class="heading-tag">USER PROFILE</span><h2>${esc(u.displayName||u.email)}</h2></div><button type="button" class="icon-btn" data-close="admin-dialog" aria-label="Close">✕</button></div><div class="empty">Loading profile…</div>`;$('#admin-dialog').showModal();let d;try{d=await cloud().userDetail(uid)}catch(e){d={error:e.code||e.message}}const p=d.planner,tickets=adminData.tickets.filter(t=>t.uid===uid),done=p?Object.keys(p.done||{}).length:0;$('#admin-content').innerHTML=`<div class="modal-heading"><div><span class="heading-tag">USER PROFILE · ${userStatus(u).toUpperCase()}</span><h2>${esc(u.displayName||'(no name)')}</h2><p class="muted">${esc(u.email)}</p></div><button type="button" class="icon-btn" data-close="admin-dialog" aria-label="Close">✕</button></div><dl class="details-list"><dt>Email</dt><dd>${u.emailVerified?'Verified':'Not verified'}</dd><dt>Joined</dt><dd>${u.createdAt?new Date(u.createdAt).toLocaleString():'—'}</dd><dt>Last active</dt><dd>${u.lastActiveAt?new Date(u.lastActiveAt).toLocaleString():'—'}</dd><dt>Timezone</dt><dd>${esc(u.timezone||'—')}</dd><dt>Notifications</dt><dd>${u.notificationsOn?'On':'Off'}</dd><dt>8 PM email</dt><dd>${u.emailOn!==false?'On':'Off'} · ${u.emailsSent||0} sent${u.lastEmailAt?' · last '+fmtWhen(u.lastEmailAt):''}</dd><dt>Planner</dt><dd>${d.error?'Couldn’t load: '+esc(d.error):p?`${p.activities.length} activities · ${done} check-ins`:'No planner yet'}</dd>${u.status!=='active'?`<dt>Status</dt><dd>${userStatus(u)}${u.suspendedUntil&&restrictedNow(u)?' until '+new Date(u.suspendedUntil).toLocaleString():''} · ${esc(u.statusReason||'no reason')} · by ${esc(u.statusUpdatedBy||'—')}</dd>`:''}</dl>${p?`<h3 class="dialog-section">Activities</h3><div class="mini-table">${p.activities.slice(0,12).map(a=>`<div><span>${esc(a.title)}</span><small>${a.category} · ${a.start}–${a.end} · ${a.repeat==='none'?a.date:a.repeat}</small></div>`).join('')||'<small>None</small>'}</div><h3 class="dialog-section">Recent activity</h3><div class="mini-table">${(p.logs||[]).slice(0,8).map(l=>`<div><span>${esc(l.type)}</span><small>${fmtWhen(l.at)} · ${esc(l.message)}</small></div>`).join('')||'<small>None</small>'}</div>`:''}<h3 class="dialog-section">Emails</h3><div class="mini-table">${(d.emailLog?.entries||[]).slice(0,8).map(e=>`<div><span>${e.type==='failed'?'Failed':e.type==='test'?'Test':'8 PM reminder'}</span><small>${fmtWhen(e.at)} · ${e.type==='failed'?esc(e.error):`${e.pending} of ${e.total} unchecked`}</small></div>`).join('')||'<small>None sent</small>'}</div><h3 class="dialog-section">Tickets</h3><div class="mini-table">${tickets.map(t=>`<div><button class="link-button" data-admin-open-ticket="${t.id}">${esc(t.subject)}</button><small>${ticketLabel[t.status]} · ${fmtWhen(t.updatedAt)}</small></div>`).join('')||'<small>None</small>'}</div><h3 class="dialog-section">Messages sent</h3><div class="mini-table">${(d.inbox||[]).map(m=>`<div><span>${esc(m.title)}</span><small>${fmtWhen(m.createdAt)} · ${m.read?'Read':'Unread'}</small></div>`).join('')||'<small>None</small>'}</div><div class="detail-actions">${userActions(u).replace(/mini-btn/g,'soft-button').replace(/>◉</,' hidden><').replace(/>✉</,'>Send message<').replace(/>↺</,'>Restore access<').replace(/>⏸</,'>Suspend<').replace(/>⦸</,'>Block<')}</div>`}
function adminForm({title,tag,fields,submit,danger}){return new Promise(resolve=>{$('#admin-content').innerHTML=`<div class="modal-heading"><div><span class="heading-tag">${tag}</span><h2>${title}</h2></div><button type="button" class="icon-btn" data-close="admin-dialog" aria-label="Close">✕</button></div><form id="admin-action-form">${fields.map(f=>`<label>${f.label}${f.type==='select'?`<select name="${f.name}">${f.options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.name}" rows="4" maxlength="${f.max||2000}" ${f.required?'required':''} placeholder="${f.placeholder||''}"></textarea>`:`<input name="${f.name}" maxlength="${f.max||200}" ${f.required?'required':''} placeholder="${f.placeholder||''}" value="${esc(f.value||'')}">`}</label>`).join('')}<p id="admin-form-error" role="alert"></p><button class="primary full ${danger?'danger-btn':''}">${submit}</button></form>`;if(!$('#admin-dialog').open)$('#admin-dialog').showModal();const form=$('#admin-action-form');form.onsubmit=e=>{e.preventDefault();resolve(Object.fromEntries(new FormData(form)))};$('#admin-dialog').addEventListener('close',()=>resolve(null),{once:true})})}
async function adminAct(fn,ok){try{await fn();$('#admin-dialog').open&&$('#admin-dialog').close();toast(ok);await loadAdmin(true)}catch(e){const el=$('#admin-form-error');if(el)el.textContent='Couldn’t save: '+(e.code||e.message);else toast('Couldn’t save: '+(e.code||e.message))}}
installAdmin();if(view==='admin'&&!window.dayformIsAdmin)view='dashboard';loadInbox();
function installAdmin(){document.body.insertAdjacentHTML('beforeend','<dialog id="admin-dialog" class="wide-dialog" aria-label="Admin"><div id="admin-content"></div></dialog>');
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset,c=cloud(),user=id=>adminData?.users.find(u=>u.id===id);
if(d.toggleTicket){openTicketId=openTicketId===d.toggleTicket?null:d.toggleTicket;render()}
if(d.markRead){try{await c.markRead(d.markRead);const m=inboxList.find(x=>x.id===d.markRead);if(m)m.read=true;loadInbox()}catch(err){toast('Couldn’t update: '+err.code)}}
if(!window.dayformIsAdmin)return;
if(d.adminTab){adminTab=d.adminTab;render()}
if('adminRefresh'in d){adminData=null;render();loadAdmin(true)}
if(d.adminUserStatus){adminUserStatus=d.adminUserStatus;render()}
if(d.adminTicketStatus){adminTicketStatus=d.adminTicketStatus;render()}
if(d.adminTicket){adminTicketId=d.adminTicket;render()}
if(d.adminOpenTicket){$('#admin-dialog').close();adminTab='tickets';adminTicketStatus='all';adminTicketId=d.adminOpenTicket;render()}
if(d.adminUser)adminUserDialog(d.adminUser);
if(d.adminMessage){const u=user(d.adminMessage),v=await adminForm({tag:'MESSAGE '+esc(u.email).toUpperCase(),title:'Send a message',fields:[{name:'title',label:'Title',required:true,max:120},{name:'body',label:'Message',type:'textarea',required:true}],submit:'Send message'});if(v)adminAct(()=>c.sendMessage(u.id,u.email,v.title,v.body),'Message sent. It appears in their Notifications page.')}
if(d.adminSuspend){const u=user(d.adminSuspend),v=await adminForm({tag:'SUSPEND '+esc(u.email).toUpperCase(),title:'Suspend this user',fields:[{name:'days',label:'Suspend for',type:'select',options:[['1','1 day'],['3','3 days'],['7','7 days'],['30','30 days']]},{name:'reason',label:'Reason (shown to the user)',type:'textarea',max:300,required:true}],submit:'Suspend user'});if(v)adminAct(()=>c.setStatus(u.id,u.email,'suspended',{days:Number(v.days),reason:v.reason}),'User suspended.')}
if(d.adminBlock){const u=user(d.adminBlock),v=await adminForm({tag:'BLOCK '+esc(u.email).toUpperCase(),title:'Block this user',danger:true,fields:[{name:'reason',label:'Reason (shown to the user)',type:'textarea',max:300,required:true}],submit:'Block user'});if(v)adminAct(()=>c.setStatus(u.id,u.email,'blocked',{reason:v.reason}),'User blocked. They can request access with a ticket.')}
if(d.adminRestore){const u=user(d.adminRestore);if(confirm(`Restore access for ${u.email}?`))adminAct(()=>c.setStatus(u.id,u.email,'active',{reason:'Access restored'}),'Access restored.')}
});
document.addEventListener('change',async e=>{if(e.target.dataset.adminTicketSet&&window.dayformIsAdmin){const t=adminData.tickets.find(x=>x.id===e.target.dataset.adminTicketSet);adminAct(()=>cloud().setTicketStatus(t.id,e.target.value,t.email),'Ticket updated.')}});
document.addEventListener('input',e=>{if(e.target.id==='admin-user-search'){adminUserQuery=e.target.value;const pos=e.target.selectionStart;render();const i=$('#admin-user-search');i.focus();i.setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='ticket-form'){e.preventDefault();const v=Object.fromEntries(new FormData(f)),btn=f.querySelector('button');btn.disabled=true;try{await cloud().createTicket(v);log('Ticket raised',`${ticketCats[v.category]}: ${v.subject}`);toast('Ticket sent. We’ll reply here.');myTicketList=null;render()}catch(err){$('#ticket-message').textContent='Couldn’t send: '+(err.code||err.message);btn.disabled=false}}
if(f.dataset.ticketReply){e.preventDefault();const v=Object.fromEntries(new FormData(f)),asAdmin=!!f.dataset.asAdmin,btn=f.querySelector('button');btn.disabled=true;try{await cloud().replyTicket(f.dataset.ticketReply,v.text,{asAdmin,status:v.status||undefined});if(asAdmin){const t=adminData.tickets.find(x=>x.id===f.dataset.ticketReply);await cloud().audit('Replied to ticket',t?.email||'',t?.subject||'');await loadAdmin(true)}else{myTicketList=null;render()}toast('Reply sent.')}catch(err){toast('Couldn’t send: '+(err.code||err.message));btn.disabled=false}}});}
